foam file
{
    format      ascii;
    class       vol vector field;
    object      u;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

dimensions      [0 1 -1 0 0 0 0];

internal field   uniform (0 0 0);

boundary field
{
    inlet
    {

        type            coded fixed value;
    	value           uniform (0 0 0);
    	name    smooth u;
    	code
    	#{
          const scalar& t = this->db().time().time output value();

          vector uav(0.25, 0, 0);
          vector dir n(1, 0, 0);

          scalar tlim(1.);
          scalar fac(8.);

          if (t<=tlim)
           {
             uav = ( ( (1 - foam::cos( 3.1415926535897932 * t/tlim) ) / fac) * dir n);
           }

          operator == (uav);
   	#};

    }

    outlet
    {
        type            zero gradient;
    }

    "(wall.*)"
    {
        type            fixed value;
        value           uniform ( 0 0 0 );
    }

    front and back
    {
        type             empty;
    }

}

